testing.dbml:
Table audit_logs {
  id integer [pk, increment, not null]
  event varchar [not null]
}

Table categories {
  id integer [pk, increment, not null]
  parent_id integer
  name varchar [not null]
}

Table comments {
  id integer [pk, increment, not null]
  user_id integer [not null]
  commentable_type varchar [not null]
  commentable_id integer [not null]
  body text [not null]
  approved tinyint(1) [not null, default: `'0'`]
  created_at datetime
  updated_at datetime

  indexes {
    (commentable_type, commentable_id) [name: 'comments_commentable_type_commentable_id_index']
  }
}

Table countries {
  id integer [pk, increment, not null]
  code varchar [not null, unique]
  name varchar [not null]
}

Table jobs {
  id integer [pk, increment, not null]
  queue varchar [not null]

  indexes {
    queue [name: 'jobs_queue_index']
  }
}

Table posts {
  id integer [pk, increment, not null]
  user_id integer [not null]
  category_id integer
  title varchar [not null]
  status varchar [not null, default: `'draft'`]
  published_at datetime
  created_at datetime
  updated_at datetime
  deleted_at datetime

  indexes {
    category_id [name: 'posts_category_id_index']
  }
}

Table role_user {
  user_id integer [not null]
  role_id integer [not null]
  assigned_at datetime

  indexes {
    (user_id, role_id) [pk]
  }
}

Table roles {
  id integer [pk, increment, not null]
  name varchar [not null]
  created_at datetime
  updated_at datetime
}

Table taggables {
  tag_id integer [not null]
  taggable_type varchar [not null]
  taggable_id integer [not null]

  indexes {
    (taggable_type, taggable_id) [name: 'taggables_taggable_type_taggable_id_index']
  }
}

Table tags {
  id integer [pk, increment, not null]
  name varchar [not null]
}

Table users {
  id integer [pk, increment, not null]
  country_id integer
  name varchar [not null]
  email varchar [not null, unique]
  email_verified_at datetime
  password varchar [not null]
  created_at datetime
  updated_at datetime
}

Ref categories_parent_id_foreign: categories.parent_id > categories.id
Ref comments_user_id_foreign: comments.user_id > users.id [delete: cascade]
Ref posts_user_id_foreign: posts.user_id > users.id [delete: cascade]
Ref role_user_role_id_foreign: role_user.role_id > roles.id [delete: cascade]
Ref role_user_user_id_foreign: role_user.user_id > users.id [delete: cascade]
Ref taggables_tag_id_foreign: taggables.tag_id > tags.id [delete: cascade]
Ref users_country_id_foreign: users.country_id > countries.id [delete: set null]
